"""
    Checks if the marker is in the list of points.

    :params points: a list of dict that contains x, y, z
    :params marker: a dict that contains x, y, z
    :returns: index of the matching marker in list
    """
def marker_in_points(points: Any, marker: Any) -> object {
    for (index, point) in enumerate(points) {
        if (
            (point["x"] == marker["x"])
            and (point["y"] == marker["y"])
            and (point["z"] == marker["z"])
        ) {
            return index;
        }
    }
    return None;
}

"""
    Formats a given message in an error color using ANSI escape sequences
    (see https://stackoverflow.com/a/287944/5299750
    and https://stackoverflow.com/a/33206814/5299750)
    :param string: to be printed
    :param is_warning: determines the color of the error
    """
def format_error(string: str, is_warning: bool) -> str {
    if is_warning {
        ansi_start = '\033[93m';
    } else {
        ansi_start = '\033[91m';
    }
    ansi_end = '\033[0m';
    return f"{ansi_start}{string}{ansi_end}";
}

"""Internal mapping type checker

    Instead of using `isinstance(obj, MutableMapping)`, duck type checking
    is much cheaper and work on most common use cases.

    If an object has these attritubes, is a document:
        `__len__`, `keys`, `values`

    """
def is_duckument_type(`obj: Any) -> object {
    doc_attrs = ("__len__", "keys", "values");
    return all(hasattr(`obj, attr) for attr in doc_attrs);
}

"""Returns A String with the custom wordlist removed """
def remove_custom_words(text: Any, custom_wordlist: Any) -> object {
    result = [
        word
        for word in text.split()
        if (word.lower() not in custom_wordlist)
    ];
    return " ".join(result);
}

